using System.Reflection;
using i25Core.Core.Entities;
using i25Core.Core.Events;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ChangeTracking;

namespace i25Core.Infrastructure.Events
{
    /// <summary>
    /// Reads the change tracker before a save and prepares the Created / Updated / Deleted
    /// events. They are dispatched after the save commits (ids are generated by then).
    /// </summary>
    internal static class ModelEventCapture
    {
        // Same housekeeping columns the audit trail ignores.
        private static readonly HashSet<string> Housekeeping = new(StringComparer.Ordinal)
        {
            nameof(BaseEntity.CreateAt),
            nameof(BaseEntity.ModifiedAt),
            nameof(BaseEntity.intConcurrencyId)
        };

        public static List<IEvent> Capture(ChangeTracker changeTracker)
        {
            var events = new List<IEvent>();

            foreach (var entry in changeTracker.Entries())
            {
                if (entry.Entity is not BaseEntity || entry.Entity is AuditLog)
                    continue;

                var clrType = entry.Metadata.ClrType;

                if (clrType.GetCustomAttribute<NoModelEventsAttribute>() != null)
                    continue;

                switch (entry.State)
                {
                    case EntityState.Added:
                        events.Add(Create(typeof(EntityCreatedEvent<>), clrType, entry.Entity));
                        break;

                    case EntityState.Deleted:
                        events.Add(Create(typeof(EntityDeletedEvent<>), clrType, entry.Entity));
                        break;

                    case EntityState.Modified:
                        var changed = ChangedProperties(entry);

                        // Only housekeeping columns changed: nothing worth announcing.
                        if (changed.Count == 0)
                            break;

                        var updated = Create(typeof(EntityUpdatedEvent<>), clrType, entry.Entity);
                        updated.GetType().GetProperty(nameof(EntityUpdatedEvent<BaseEntity>.ChangedProperties))!
                            .SetValue(updated, changed);
                        events.Add(updated);
                        break;
                }
            }

            return events;
        }

        private static List<string> ChangedProperties(EntityEntry entry)
        {
            return entry.Properties
                .Where(p => p.IsModified && !Housekeeping.Contains(p.Metadata.Name))
                .Select(p => p.Metadata.Name)
                .ToList();
        }

        private static IEvent Create(Type openGenericEvent, Type entityType, object entity)
        {
            var @event = Activator.CreateInstance(openGenericEvent.MakeGenericType(entityType))!;
            @event.GetType().GetProperty(nameof(EntityCreatedEvent<BaseEntity>.Entity))!.SetValue(@event, entity);
            return (IEvent)@event;
        }
    }
}
